head.b:skin:
/* Klik Hadir engine — gaya dasar template (detail di engine/core.css) */
#navbar-iframe{display:none!important}
.kh-config-wrap{display:none!important}
#Attribution1,.Attribution,.widget.Attribution{display:none!important}
html,body{margin:0;padding:0}
#app{min-height:100vh}
#katalog{max-width:1120px;margin:0 auto;padding:28px 16px}
.kh-error{max-width:640px;margin:48px auto;padding:24px 20px;border:1px solid #e5c07b;background:#fff8ec;border-radius:12px;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;color:#5b4a2f;line-height:1.65;font-size:15px}
.kh-error strong{color:#8a5a1e;display:block;margin-bottom:8px;font-size:17px}

body.script:
//
/* Bootstrap Klik Hadir: pilih mode dari DOM, baca versi dari config,
   lalu muat engine yang sesuai dari jsDelivr sebagai ES module. */
(function () {
  'use strict';

  var CDN_REPO = 'https://cdn.jsdelivr.net/gh/ilmaanisa2605-spark/undangan@';

  function tampilkanError(pesan) {
    var target = document.getElementById('app') ||
                 document.getElementById('katalog') ||
                 document.getElementById('kh-main') ||
                 document.body;
    var box = document.createElement('div');
    box.className = 'kh-error';
    var judul = document.createElement('strong');
    judul.textContent = 'Ups, undangannya belum bisa ditampilkan.';
    var isi = document.createElement('span');
    isi.textContent = pesan;
    box.appendChild(judul);
    box.appendChild(isi);
    target.innerHTML = '';
    target.appendChild(box);
  }

  function mulai() {
    var modeKatalog = !!document.getElementById('katalog');
    var v = '1.0.0';

    if (!modeKatalog) {
      /* Mode undangan: ambil versi engine dari blok config Halaman */
      try {
        var cfgEl = document.getElementById('config');
        if (cfgEl) {
          var teks = cfgEl.textContent || cfgEl.innerText || '{}';
          var cfgAwal = JSON.parse(teks);
          if (cfgAwal && cfgAwal.v) v = String(cfgAwal.v);
        }
      } catch (e) {
        v = '1.0.0';
      }
    }

    var BASE = CDN_REPO + v;
    window.__KH_BASE = BASE;

    var berkas = modeKatalog ? 'catalog.js' : 'loader.js';
    import(BASE + '/engine/' + berkas).catch(function () {
      tampilkanError('Gagal memuat engine dari internet (' + berkas + '). ' +
        'Periksa koneksi internet, lalu muat ulang halaman ini. ' +
        'Jika masih gagal, hubungi pembuat undangan.');
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', mulai);
  } else {
    mulai();
  }
})();
//
